begin;
create extension if not exists pgtap with schema extensions;
select plan(22);
delete from public.team_members;
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000000801','general.designer@example.test'),('00000000-0000-4000-8000-000000000802','general.operator@example.test');
insert into public.team_members(id,auth_user_id,email,display_name) values
('00000000-0000-4000-8000-000000000811','00000000-0000-4000-8000-000000000801','general.designer@example.test','Diseño'),
('00000000-0000-4000-8000-000000000812','00000000-0000-4000-8000-000000000802','general.operator@example.test','Taller');
insert into public.team_member_roles(member_id,role) values('00000000-0000-4000-8000-000000000811','designer'),('00000000-0000-4000-8000-000000000812','operator');
set local role authenticated;
set local "request.jwt.claim.sub"='00000000-0000-4000-8000-000000000801';
select public.save_customer('00000000-0000-4000-8000-000000000821',null,'{"display_name":"Cliente imanes"}');
select lives_ok($$select public.create_direct_order('00000000-0000-4000-8000-000000000822','00000000-0000-4000-8000-000000000821',null,null,'Indicaciones privadas','[{"description":"Delfines","quantity":100,"amount":"100","technical_sheet":{"printing_color":"NO COPIAR"}},{"description":"Tortugas","quantity":200,"amount":"200"}]','{"amount":"40","paid_on":"1901-01-15","method":"cash"}',null,null,'Imanes promocionales','{"printing_color":"Color","number_ranges":[{"point_of_sale":"0003","from":"000001","to":"000100"}]}')$$,'Alta con descripción y una ficha común');
select is((select work_description from public.orders where id='00000000-0000-4000-8000-000000000822'),'Imanes promocionales','Guarda descripción general');
select is((select technical_sheet->'number_ranges'->0->>'point_of_sale' from public.orders where id='00000000-0000-4000-8000-000000000822'),'0003','La ficha común conserva los ceros');
select is((select count(*) from public.order_items where order_id='00000000-0000-4000-8000-000000000822' and technical_sheet='{}'),2::bigint,'Descarta fichas individuales en todos los ítems');
select is((public.order_money('00000000-0000-4000-8000-000000000822')->>'paid')::numeric,40::numeric,'La seña se registra igual');
select public.create_direct_order('00000000-0000-4000-8000-000000000822',null,null,null,'','[]',null,null,null,'Otro texto','{}');
select is((select work_description from public.orders where id='00000000-0000-4000-8000-000000000822'),'Imanes promocionales','Un reintento no pisa la descripción');
select public.create_direct_order('00000000-0000-4000-8000-000000000823','00000000-0000-4000-8000-000000000821',null,null,'','[{"description":"Delfines nuevos","quantity":50,"amount":"80"}]',null,null,'00000000-0000-4000-8000-000000000822');
select is((select work_description from public.orders where id='00000000-0000-4000-8000-000000000823'),'Imanes promocionales','La duplicación copia la descripción general');
select is((select technical_sheet->>'printing_color' from public.orders where id='00000000-0000-4000-8000-000000000823'),'Color','La duplicación copia una sola ficha común');
select is((public.order_money('00000000-0000-4000-8000-000000000823')->>'paid')::numeric,0::numeric,'La duplicación no copia pagos');
select throws_ok($$select public.create_direct_order('00000000-0000-4000-8000-000000000824','00000000-0000-4000-8000-000000000821',null,null,'','[{"description":"Modelo","quantity":1,"amount":"5"}]',null,null,null,'Imanes','{"invalid":"x"}')$$,'22023',null,'Valida la ficha común en SQL');
select is((select count(*) from public.orders where id='00000000-0000-4000-8000-000000000824'),0::bigint,'Una ficha inválida no crea la nota');
set local "request.jwt.claim.sub"='00000000-0000-4000-8000-000000000802';
select is(public.production_order('00000000-0000-4000-8000-000000000822')->>'work_description','Imanes promocionales','Producción ve la descripción común');
select is(public.production_order('00000000-0000-4000-8000-000000000822')->'technical_sheet'->>'printing_color','Color','Producción ve la ficha común');
select ok(not(public.production_order('00000000-0000-4000-8000-000000000822')?'total'),'La proyección de taller sigue sin dinero');
select throws_ok($$select public.save_order_work_details('00000000-0000-4000-8000-000000000822',1,'[]','Cambio','{}')$$,'42501',null,'Producción no edita la ficha de Diseño');
select public.complete_production('00000000-0000-4000-8000-000000000822',null,'Cierre de ítems');
set local "request.jwt.claim.sub"='00000000-0000-4000-8000-000000000801';
select lives_ok($$select public.save_order_work_details('00000000-0000-4000-8000-000000000822',1,(select jsonb_agg(jsonb_build_object('id',id,'client_description',client_description,'specifications',specifications,'technical_sheet','{}'::jsonb)) from public.order_items where order_id='00000000-0000-4000-8000-000000000822'),'Imanes terminados','{"printing_color":"Negro"}')$$,'Se puede editar la descripción y ficha general');
select is((select technical_sheet->>'printing_color' from public.orders where id='00000000-0000-4000-8000-000000000822'),'Negro','Guarda la ficha nueva');
select is((select total from public.orders where id='00000000-0000-4000-8000-000000000822'),300::numeric,'Editar ficha no cambia importes');
select is((public.order_money('00000000-0000-4000-8000-000000000822')->>'paid')::numeric,40::numeric,'Editar ficha no cambia cobros');
select is((select count(*) from public.order_items where order_id='00000000-0000-4000-8000-000000000822' and production_status='completed'),2::bigint,'Editar ficha conserva cierres de ítems');
select throws_ok($$select public.save_order_work_details('00000000-0000-4000-8000-000000000822',1,'[]','Cambio viejo','{}')$$,'40001',null,'La revisión impide sobrescribir cambios concurrentes');
select ok(not has_function_privilege('authenticated','private.save_order_items_before_header(uuid,integer,jsonb)','EXECUTE'),'No permite omitir la validación pública');
reset role;
select * from finish();
rollback;
